import java.util.Scanner;

public class RatioEvaluator {
    static long min_num, min_den;
    static long a_best, b_best;

    public static long compute_gcd(long a, long b) {
        while (b != 0) {
            long temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void evaluate_ratio(long x, long y, long b, long a) {
        if (a < 0) return;
        long g = compute_gcd(a, b);
        a /= g;
        b /= g;
        long numerator = Math.abs(b * x - a * y);
        long denominator = b * y;
        long g2 = compute_gcd(numerator, denominator);
        numerator /= g2;
        denominator /= g2;
        if (numerator * min_den < min_num * denominator) {
            min_num = numerator;
            min_den = denominator;
            a_best = a;
            b_best = b;
            return;
        }
        if (numerator * min_den == denominator * min_num) {
            if (b < b_best) {
                a_best = a;
                b_best = b;
                return;
            }
            if (b > b_best) {
                return;
            }
            if (a < a_best) {
                a_best = a;
                b_best = b;
                return;
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        min_num = 100000;
        min_den = 1;
        long x = scanner.nextLong();
